package com.aistock.gateway;
import com.aistock.common.ApiExceptionHandler;import com.fasterxml.jackson.databind.ObjectMapper;import java.util.*;import org.junit.jupiter.api.Test;import org.mockito.ArgumentCaptor;import org.springframework.http.ResponseEntity;import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class VerificationProxyTest {
 @Test void exactReadonlyVerificationRoutesForwardOnlySessionAndPage()throws Exception{var client=mock(ForecastPublicClient.class);when(client.get(anyString(),anyMap(),anyMap())).thenReturn(ResponseEntity.ok("{\"code\":\"OK\",\"data\":{}}".getBytes()));var mvc=MockMvcBuilders.standaloneSetup(new ForecastApiProxyController(client,new ObjectMapper())).setControllerAdvice(new ApiExceptionHandler()).build();String id="11111111-1111-1111-1111-111111111111",version="22222222-2222-2222-2222-222222222222";for(var tail:List.of("","/"+version)){String path="/api/v1/predictions/"+id+"/verifications"+tail;mvc.perform(get(path).param("page","2").param("ownerId","forged").header("Cookie","AISTOCK_SESSION=fixture").header("X-Service-Token","forged").header("X-Role","ADMIN")).andExpect(status().isOk());var headers=ArgumentCaptor.forClass(Map.class);var query=ArgumentCaptor.forClass(Map.class);verify(client).get(eq(path.substring(8)),query.capture(),headers.capture());assertEquals(Map.of("page","2"),query.getValue());assertEquals("AISTOCK_SESSION=fixture",headers.getValue().get("Cookie"));assertFalse(headers.getValue().containsKey("X-Service-Token"));assertFalse(headers.getValue().containsKey("X-Role"));}}
 @Test void verificationAllowlistDoesNotExposeWritesInternalOrArbitrarySuffix(){String path="/api/v1/predictions/11111111-1111-1111-1111-111111111111/verifications";assertFalse(ProxyHeaderPolicy.allowed("POST",path));assertFalse(ProxyHeaderPolicy.allowed("DELETE",path));assertFalse(ProxyHeaderPolicy.allowed("GET",path+"/operations"));assertFalse(ProxyHeaderPolicy.allowed("GET",path+"/11111111-1111-1111-1111-111111111111/extra"));assertFalse(ProxyHeaderPolicy.allowed("GET","/internal/v1/predictions/11111111-1111-1111-1111-111111111111/verification"));}
}
